function FiyatGoster({ fiyat, indirimli }: { fiyat: number; indirimli: number | null }) {
  const fmt = (v: number) => `${(v / 100).toFixed(2).replace('.', ',')} ₺`
  if (!indirimli) return <span style={{ fontWeight: 900, fontSize: 18 }}>{fmt(fiyat)}</span>
  return (
    <span style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}>
      <span style={{ fontWeight: 900, fontSize: 18, color: '#e11d48' }}>{fmt(indirimli)}</span>
      <span style={{ fontSize: 13, textDecoration: 'line-through', color: '#555' }}>{fmt(fiyat)}</span>
    </span>
  )
}

